
import type { InventoryActionRequiredInput } from './InventoryActionRequiredInput.js';
import type { InventoryReservationOwnerInput } from './InventoryReservationOwnerInput.js';
import type { InventoryRoutingSourceInput } from './InventoryRoutingSourceInput.js';
import type { ReservationLineInput } from './ReservationLineInput.js';

/** A claim on stock. Quantity moves from held to committed to consumed, and can be released or reallocated. */ export type InventoryReservationInput = { /** How the reservation ended. mixed when more than one terminal outcome applied. */ "closed_reason"?: "consumed" | "released" | "expired" | "reallocated" | "mixed" | null; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "idempotency_key": string; /** Present when the claim needs a merchant action before commerce can continue. */ "inventory_action_required"?: InventoryActionRequiredInput; "inventory_reservation_id": string; "inventory_routing_source": InventoryRoutingSourceInput; "lines": Array<ReservationLineInput>; "owner": InventoryReservationOwnerInput; "replacement_inventory_reservation_id"?: string; "source_inventory_reservation_id"?: string; /** active while any held or committed quantity remains; closed once none does. */ "status": "active" | "closed"; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string | globalThis.Date; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
